from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.client.decorators import api_version_check
from pyvkteamsclient.tracer import tracer


class CloudMethods(BaseClient):
    """
    Методы группы 'Облако' из https://im-docs.corp.mail.ru/
    """

    @api_version_check(min_version=90)
    @tracer.start_as_current_span("cloud.rapi_cloud_folder_list")
    def rapi_cloud_folder_list(self, folder: str = "/"):
        """
        Возвращает содержимое папки пользователя.
        """
        return self.post(
            "rapi/cloud/folder/list",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"folder": folder},
            },
        )

    @api_version_check(min_version=90)
    @tracer.start_as_current_span("cloud.rapi_cloud_initFileSave")
    def rapi_cloud_initFileSave(self, file_id: str, source: str, folder: str = "/"):
        """
        Запускает процесс сохранения файла, загруженного ранее в мессенджер,
        в облаке. Загрузка в облако происходит асинхронно.
        Результат операции можно отследить, подписавшись на событие
        cloudFileStatus (eventSubscribe + fetchEvents).
        """
        return self.post(
            "rapi/cloud/initFileSave",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "fileId": file_id,
                    "source": source,
                    "folder": folder,
                },
            },
        )

    @api_version_check(min_version=90)
    @tracer.start_as_current_span("cloud.rapi_cloud_openFile")
    def rapi_cloud_openFile(self, file_id: str, source: str):
        """
        Возвращает ссылку на файл в облаке пользователя.
        """
        return self.post(
            "rapi/cloud/openFile",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"fileId": file_id, "source": source},
            },
        )

    @api_version_check(min_version=90)
    @tracer.start_as_current_span("cloud.rapi_cloud_cancelSave")
    def rapi_cloud_cancelSave(self, file_id: str, source: str):
        """
        Сохранение файла в облаке реализовано как асинхронная операция.
        Данный запрос пытается ее отменить.

        Сервер не допускает ситуации, в которой существует
        несколько активных запросов для пары (файл, пользователь),
        поэтому никаких дополнительных идентификаторов не требуется.

        По ответу на запрос можно определить, удалось отменить
        сохранение или нет.

        Актуальное состояние придет в событии cloudFileStatus.
        """
        return self.post(
            "rapi/cloud/cancelSave",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"fileId": file_id, "source": source},
            },
        )
